create table eba_demo_appr_approvers (
    id                 number
        generated by default on null as identity
    not null enable,
    username           varchar2(50 char),
    task_def_static_id varchar2(50 char),
    job_codes          varchar2(50 char),
    participant_role   varchar2(8 char),
    min_salary         number
);

alter table eba_demo_appr_approvers
    add constraint approvers_id_pk primary key ( id )
        using index enable;

alter table eba_demo_appr_approvers
    add constraint approvers_particpant_role_ck
        check ( participant_role = 'APPROVER'
                or participant_role = 'ADMIN' ) enable;


